function(params){
  if (game.state !== 'play') return { message: '⚠️ 请先按 Enter 开始游戏再使用道具', error: true };
  var T = 32;
  var range = (params && params.range ? params.range : 7) * T;
  var vTol = (params && params.spread ? params.spread : 2) * T;
  var dir = player.face >= 0 ? 1 : -1;
  var px = player.x + player.w/2, py = player.y + player.h/2;
  var kills = 0;
  for (var s = 1; s <= range; s += 8){
    particles.push({ x: px + dir*s, y: py, vx: 0, vy: 0, t: 0 });
  }
  for (var i = enemies.length - 1; i >= 0; i--){
    var e = enemies[i];
    if (e.ghost) continue;
    var ex = e.x + e.w/2, ey = e.y + e.h/2;
    var dx = (ex - px) * dir;
    var dy = Math.abs(ey - py);
    if (dx > 0 && dx <= range && dy <= vTol){
      e.flat = 30;
      api.addScore(50);
      kills++;
      for (var k = 0; k < 7; k++){
        particles.push({ x: ex, y: ey, vx: (Math.random()*2-1)*4, vy: -6 + (Math.random()*2-1)*3, t: 0 });
      }
    }
  }
  console.log('[长弓] 命中 ' + kills + ' 个敌人');
  return { message: '🏹 箭气命中 ' + kills + ' 个敌人！' };
}
